final class Round4LiveScene {
    static final BlockPos O=new BlockPos(0,65,0);
    static Path root(){return Path.of(System.getProperty("thaumcraft.r3.root"),System.getProperty("thaumcraft.polish.output","analysis/golems-aura-tools-audit/round4/live"));}
    static ServerPlayer player;static int stage=-1,age;static ThaumicGolem golem;
    static final List<String> checks=new ArrayList<>();
    static void check(boolean condition,String description){if(!condition)throw new AssertionError(description);checks.add(description);try{Files.writeString(root().resolve("server-checks.json"),new com.google.gson.GsonBuilder().setPrettyPrinting().create().toJson(checks));}catch(Exception e){throw new RuntimeException(e);}}
    static void register(MinecraftServer server){try{Files.createDirectories(root());Files.deleteIfExists(root().resolve("ready.json"));Files.deleteIfExists(root().resolve("request.json"));}catch(Exception e){throw new RuntimeException(e);}
        NeoForge.EVENT_BUS.addListener((PlayerEvent.PlayerLoggedInEvent e)->{if(e.getEntity() instanceof ServerPlayer p){player=p;server.getPlayerList().op(p.getGameProfile());thaumcraft.knowledge.KnowledgeService.initialize(p);thaumcraft.knowledge.KnowledgeService.mutate(p,k->{k.clearScans();for(var a:Aspect.all().values())k.discover(a);return true;});}});
        NeoForge.EVENT_BUS.addListener((PlayerEvent.PlayerLoggedOutEvent e)->{if(e.getEntity()==player)server.halt(false);});
        NeoForge.EVENT_BUS.addListener((ServerTickEvent.Post e)->{if(e.getServer()!=server||player==null)return;try{
            if(stage>=0){age++;var l=player.serverLevel();if(stage==2&&age==20)l.setBlockAndUpdate(O.above().east(),Blocks.REDSTONE_BLOCK.defaultBlockState());if(stage==2&&age==95)l.removeBlock(O.above().east(),false);
                if(stage==8&&age%50==0){var state=new net.minecraft.nbt.CompoundTag();golem.addAdditionalSaveData(state);var amounts=new ArrayList<String>();for(int h=1;h<=3;h++){var tile=(TransportBlockEntity)l.getBlockEntity(O.above(h));var cap=l.getCapability(EssentiaCapabilities.TRANSPORT,O.above(h),null);amounts.add(h+":"+tile.store.amount()+":"+(cap==null?"null":cap.getEssentiaAmount(Direction.UP)+"/"+cap.canOutputTo(Direction.UP)));}var gs=Mob.class.getDeclaredField("goalSelector");gs.setAccessible(true);var selector=(net.minecraft.world.entity.ai.goal.GoalSelector)gs.get(golem);var goals=new ArrayList<String>();for(var w:selector.getAvailableGoals())if(w.getGoal() instanceof GolemWorkGoal work){for(var name:List.of("target","job","timeout","searchAfter")){var field=GolemWorkGoal.class.getDeclaredField(name);field.setAccessible(true);goals.add(name+"="+field.get(work));}goals.add("running="+w.isRunning());}Files.writeString(root().resolve("golem-debug-"+age+".json"),new com.google.gson.GsonBuilder().setPrettyPrinting().create().toJson(Map.of("nbt",state.toString(),"alembics",amounts,"inactive",golem.inactive(),"source",golem.source().toString(),"navigation",String.valueOf(golem.getNavigation().getTargetPos()),"goals",goals)));}
                if(stage==8&&age==500){int total=0;for(int i=0;i<3;i++)total+=((TransportBlockEntity)l.getBlockEntity(O.east(4).offset(0,0,i))).store.amount();check(total==48&&golem.essentiaAmount==0,"ordinary golem scheduler drains three elevated alembics into marked jars: 48 essentia");}
            }
            var request=root().resolve("request.json");if(!Files.exists(request))return;int next=Integer.parseInt(Files.readString(request).trim());if(next==stage)return;
            prepare(next);stage=next;age=0;Files.writeString(root().resolve("ready.json"),Integer.toString(stage));Files.writeString(root().resolve("server-checks.json"),new com.google.gson.GsonBuilder().setPrettyPrinting().create().toJson(checks));
        }catch(Throwable error){error.printStackTrace();try{Files.writeString(root().resolve("server-failure.txt"),error.toString());}catch(Exception ignored){}server.halt(false);}});
    }
    static AuraNodeBlockEntity node(ServerLevel l,BlockPos p){l.setBlockAndUpdate(p,R2Content.AURA_NODE.get().defaultBlockState());var n=(AuraNodeBlockEntity)l.getBlockEntity(p);n.initialize(Map.of("aer",150,"aqua",150,"terra",150,"ignis",150,"ordo",150,"perditio",150),NodeState.Type.NORMAL,NodeState.Modifier.NONE);return n;}
    static void prepare(int next){var l=player.serverLevel();player.closeContainer();player.stopUsingItem();player.removeAllEffects();player.getInventory().clearContent();player.getInventory().selected=0;player.connection.send(new net.minecraft.network.protocol.game.ClientboundSetCarriedItemPacket(0));for(var slot:EquipmentSlot.values())if(slot.getType()==EquipmentSlot.Type.HUMANOID_ARMOR)player.setItemSlot(slot,ItemStack.EMPTY);for(var entity:l.getEntitiesOfClass(Mob.class,new AABB(O).inflate(25)))entity.discard();for(var entity:l.getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new AABB(O).inflate(25)))entity.discard();for(var p:BlockPos.betweenClosed(O.offset(-8,-1,-8),O.offset(8,7,8)))l.setBlock(p,p.getY()==64?Blocks.STONE.defaultBlockState():Blocks.AIR.defaultBlockState(),2);l.setDayTime(6000);player.setGameMode(GameType.CREATIVE);player.getAbilities().flying=true;player.onUpdateAbilities();player.teleportTo(.5,65,4.5);player.setYRot(180);player.setXRot(8);
        switch(next){
            case 20->{player.setGameMode(GameType.SURVIVAL);int slot=9;for(var name:List.of("helmet","chestplate","leggings")){var stack=new ItemStack(R3Equipment.ARMOR.get("void_robe_"+name).get());player.getInventory().setItem(slot++,stack.copy());player.setItemSlot(name.equals("helmet")?EquipmentSlot.HEAD:name.equals("chestplate")?EquipmentSlot.CHEST:EquipmentSlot.LEGS,stack);}}
            case 0->{for(int x=-2;x<=2;x++)for(int y=0;y<4;y++)l.setBlockAndUpdate(O.offset(x,y,0),Blocks.STONE.defaultBlockState());player.server.getCommands().performPrefixedCommand(player.createCommandSourceStack(),"thaumcraft node");}
            case 1->{for(int x=-3;x<=3;x++)for(int y=0;y<4;y++)l.setBlockAndUpdate(O.offset(x,y,0),Blocks.STONE.defaultBlockState());l.setBlockAndUpdate(O.offset(-1,1,-1),Blocks.DIAMOND_ORE.defaultBlockState());l.setBlockAndUpdate(O.offset(0,1,-1),Blocks.GOLD_ORE.defaultBlockState());l.setBlockAndUpdate(O.offset(1,1,-1),Blocks.IRON_ORE.defaultBlockState());l.setBlockAndUpdate(O.offset(2,0,-1),Blocks.WATER.defaultBlockState());l.setBlockAndUpdate(O.offset(-2,0,-1),Blocks.LAVA.defaultBlockState());player.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(R3Equipment.TOOLS.get("elemental_pickaxe").get()));}
            case 2->{node(l,O);l.setBlockAndUpdate(O.below(),R3Content.NODE_STABILIZER.get().defaultBlockState());l.setBlockAndUpdate(O.above(),R3Content.NODE_CONVERTER.get().defaultBlockState());player.teleportTo(2.5,65,4.5);}
            case 3->{player.setItemSlot(EquipmentSlot.HEAD,new ItemStack(R2Content.GOGGLES.get()));node(l,O.above());var wand=new ItemStack(R3Equipment.SCEPTRE.get());wand.set(WandComponents.PARTS.get(),new thaumcraft.api.wands.WandParts("wood","gold"));player.setItemInHand(InteractionHand.MAIN_HAND,wand);}
            case 14,15->{player.setItemSlot(EquipmentSlot.HEAD,new ItemStack(R2Content.GOGGLES.get()));node(l,O.above());var wand=new ItemStack(next==14?R3Equipment.WAND.get():R3Equipment.STAFF.get());wand.set(WandComponents.PARTS.get(),new thaumcraft.api.wands.WandParts(next==14?"greatwood":"silverwood_staff","gold"));player.setItemInHand(InteractionHand.MAIN_HAND,wand);}
            case 4->{player.setItemInHand(InteractionHand.MAIN_HAND,Round3Verification.wand());int i=9;for(var item:R3Equipment.FOCI.values())player.getInventory().setItem(i++,new ItemStack(item.get()));}
            case 5->{l.setBlockAndUpdate(O,R2Content.ARCANE_WORKBENCH.get().defaultBlockState());l.setBlockAndUpdate(O.above(),R3Content.WORKBENCH_CHARGER.get().defaultBlockState());l.setBlockAndUpdate(O.west(3).above(),R3Content.ENERGIZED_NODE.get().defaultBlockState());var table=(TableBlockEntity)l.getBlockEntity(O);var wand=new ItemStack(R3Equipment.SCEPTRE.get());wand.set(WandComponents.PARTS.get(),new thaumcraft.api.wands.WandParts("wood","gold"));table.setItem(10,wand);player.openMenu(table);}
            case 6->{l.setBlockAndUpdate(O,R3Content.ALCHEMY_FURNACE.get().defaultBlockState());var furnace=(AlchemyFurnaceBlockEntity)l.getBlockEntity(O);furnace.setItem(0,new ItemStack(Items.OAK_LOG,32));furnace.setItem(1,new ItemStack(Items.COAL,64));player.openMenu(furnace);}
            case 7->{player.setGameMode(GameType.SURVIVAL);int i=9;for(var item:List.of(R3Equipment.WAND,R3Equipment.STAFF,R3Equipment.SCEPTRE))for(var rod:List.of("greatwood","silverwood")){var w=new ItemStack(item.get());w.set(WandComponents.PARTS.get(),new thaumcraft.api.wands.WandParts(rod,"gold"));player.getInventory().setItem(i++,w);}player.getInventory().setItem(i++,new ItemStack(R3Content.ALEMBIC.get().asItem()));player.getInventory().setItem(i++,new ItemStack(R3Equipment.ARMOR.get("void_robe_helmet").get()));}
            case 8->{l.setBlockAndUpdate(O,R3Content.ALCHEMY_FURNACE.get().defaultBlockState());int i=0;for(var a:List.of(Aspects.FIRE,Aspects.WATER,Aspects.EARTH)){var ale=Round3Verification.transport(l,O.above(++i),R3Content.ALEMBIC.get());ale.store.setAspects(new AspectList().add(a,16));var jar=Round3Verification.transport(l,O.east(4).offset(0,0,i-1),R3Content.WARDED_JAR.get());jar.store.filter(a);}
                var body=new ItemStack(R3Equipment.GOLEM_BODIES.get(GolemMaterial.THAUMIUM).get());net.minecraft.world.item.component.CustomData.update(net.minecraft.core.component.DataComponents.CUSTOM_DATA,body,t->{t.putInt("core",6);t.putBoolean("advanced",true);});golem=R3Entities.GOLEM.get().create(l);golem.initialize(GolemMaterial.THAUMIUM,player.getUUID(),O.south(),Direction.SOUTH,body);golem.moveTo(.5,65,1.5);l.addFreshEntity(golem);for(i=0;i<3;i++)golem.mark(new GolemMarker(l.dimension(),O.east(4).offset(0,0,i),Direction.UP,-1),false);player.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(R3Equipment.GOLEM_BELL.get()));}
            case 9->{l.setBlockAndUpdate(O,R3Content.VIS_RELAY.get().defaultBlockState());l.setBlockAndUpdate(O.west(3),R3Content.ENERGIZED_NODE.get().defaultBlockState());int i=0;for(var shard:R2Content.SHARDS)player.getInventory().setItem(i++,new ItemStack(shard.get()));player.getInventory().setItem(i,new ItemStack(R3Content.BALANCED_SHARD.get()));player.teleportTo(.5,65,2.5);player.setXRot(30);}
            case 10->{var node=node(l,O);node.state.type=NodeState.Type.PURE;node.state.modifier=NodeState.Modifier.BRIGHT;node.changedAndSync();var clone=node.getBlockState().getBlock().getCloneItemStack(node.getBlockState(),new BlockHitResult(O.getCenter(),Direction.UP,O,false),l,O,player);check(clone.has(net.minecraft.core.component.DataComponents.BLOCK_ENTITY_DATA),"plain creative pick preserves node components");check(clone.get(net.minecraft.core.component.DataComponents.BLOCK_ENTITY_DATA).copyTag().getCompound("vis").getInt("aer")==150,"picked node retains all aspect values");
                player.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(R3Content.NODE_STABILIZER.get().asItem()));var hit=new BlockHitResult(O.getCenter(),Direction.DOWN,O,false);l.removeBlock(O.below(),false);check(player.gameMode.useItemOn(player,l,player.getMainHandItem(),InteractionHand.MAIN_HAND,hit).consumesAction(),"real item interaction places stabilizer below aura node");check(l.getBlockState(O.below()).is(R3Content.NODE_STABILIZER.get()),"stabilizer occupies lower construction position");player.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(R3Content.NODE_CONVERTER.get().asItem()));hit=new BlockHitResult(O.getCenter(),Direction.UP,O,false);check(player.gameMode.useItemOn(player,l,player.getMainHandItem(),InteractionHand.MAIN_HAND,hit).consumesAction(),"real item interaction places converter above aura node");}
            case 12->{player.setGameMode(GameType.SURVIVAL);player.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(R2Content.THAUMOMETER.get()));player.getInventory().setItem(9,new ItemStack(Items.DIAMOND));check(!thaumcraft.knowledge.InventoryScanService.holding(player),"selected hotbar scanner cannot scan inventory without cursor pickup");}
            case 13->{var body=new ItemStack(R3Equipment.GOLEM_BODIES.get(GolemMaterial.THAUMIUM).get());net.minecraft.world.item.component.CustomData.update(net.minecraft.core.component.DataComponents.CUSTOM_DATA,body,t->{t.putInt("core",6);t.putBoolean("advanced",true);t.putByteArray("upgrades",new byte[]{0,4,1});t.putString("deco","HG");});golem=R3Entities.GOLEM.get().create(l);golem.initialize(GolemMaterial.THAUMIUM,player.getUUID(),O.south(),Direction.SOUTH,body);golem.setNoAi(true);golem.moveTo(.5,65,.5);l.addFreshEntity(golem);player.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(R3Equipment.GOLEM_BELL.get()));}
            case 11->{golem=Round3Verification.golem(l,O,6,GolemMaterial.CLAY,false);golem.setNoAi(true);golem.moveTo(.5,65,.5);player.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(R2Content.THAUMOMETER.get()));}
        }
        player.inventoryMenu.broadcastChanges();
    }
}
